import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int M = sc.nextInt();

        int[] dp_vals = new int[n + 1];
        int[] accu_vals = new int[n + 1];

        if (n >= 1) {
            dp_vals[1] = 1;
            accu_vals[1] = 1;
        }
        if (n >= 2) {
            dp_vals[2] = 1;
            accu_vals[2] = 2;
        }

        for (int i = 3; i <= n; i++) {
            dp_vals[i] = accu_vals[i - 1];
            int sqrt_limit = (int) Math.sqrt(i);
            for (int j = 1; j <= sqrt_limit; j++) {
                if (i % j == 0) {
                    dp_vals[i] += dp_vals[j];
                    dp_vals[i] %= M;
                    if (j > 1 && j * j < i) {
                        dp_vals[i] += dp_vals[i / j];
                        dp_vals[i] %= M;
                    }
                }
            }
            accu_vals[i] = (accu_vals[i - 1] + dp_vals[i]) % M;
        }

        System.out.println(accu_vals[n]);
        sc.close();
    }
}
